# ============================================================
# DATA
# ============================================================
BASE_DIR = Path(__file__).resolve().parent
DATA_CANDIDATES = [
    BASE_DIR / "data" / "dashboard_data_final.csv",
    BASE_DIR / "data" / "dashboard_data.csv",
]

@st.cache_data
def load_data():
    for path in DATA_CANDIDATES:
        if path.exists():
            return pd.read_csv(path), path
    return None, DATA_CANDIDATES[0]

df, DATA_PATH = load_data()

if df is None:
    st.error(
        f"Dashboard data not found.\n\nExpected:\n`{DATA_CANDIDATES[0]}`"
    )
    st.stop()

df.columns = [str(c).strip() for c in df.columns]

required = ["case_id", "category", "severity", "decision", "ai_confidence", "grounded"]
missing = [c for c in required if c not in df.columns]

if missing:
    st.error("Missing required columns: " + ", ".join(missing))
    st.stop()


def parse_bool(v):
    if pd.isna(v):
        return False
    if isinstance(v, bool):
        return v
    return str(v).strip().lower() in {"true", "1", "yes", "y"}


df["grounded"] = df["grounded"].apply(parse_bool)

total = len(df)
accepted = int((df["decision"] == "Accepted").sum())
edited = int((df["decision"] == "Edited").sum())
rejected = int((df["decision"] == "Rejected").sum())
corrections = edited + rejected
grounded = int(df["grounded"].sum())
flags = total - grounded
agreement = accepted / total if total else 0
category_count = int(df["category"].nunique())


def safe_text(value, fallback="Not available"):
    if pd.isna(value) or str(value).strip() == "":
        return fallback
    return str(value)


def themed(fig, height=350):
    fig.update_layout(
        height=height,
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#dfeaf1", family="Inter"),
        margin=dict(l=10, r=18, t=15, b=10),
        legend=dict(
            bgcolor="rgba(0,0,0,0)",
            font=dict(color="#cbd9e2", size=11),
        ),
    )
    fig.update_xaxes(
        gridcolor="rgba(120,150,170,.10)",
        zerolinecolor="rgba(120,150,170,.10)",
    )
    fig.update_yaxes(
        gridcolor="rgba(120,150,170,.10)",
        zerolinecolor="rgba(120,150,170,.10)",
    )
    return fig


