# BRAND
# ============================================================
st.markdown(
    """
    <div class="brand-row">
        <div class="brand-left">
            <div class="brand-mark">◈</div>
            <div>
                <div class="brand-name">NetSage AI</div>
                <div class="brand-sub">Network assurance / grounded diagnosis system</div>
            </div>
        </div>
        <div class="status-pill">
            <span class="status-dot"></span>
            Evaluation system operational
        </div>
    </div>
    """,
    unsafe_allow_html=True,
)


# ============================================================
# COMMAND NAVIGATION — BUTTONS, NOT RADIO
# ============================================================
PAGES = [
    "Overview",
    "AI Diagnosis",
    "Cases",
    "Evaluation",
    "Responsible AI",
]

if "page" not in st.session_state:
    st.session_state.page = "Overview"

st.markdown('<div class="nav-label">Command Center / Navigation</div>', unsafe_allow_html=True)
st.markdown('<div class="nav-shell">', unsafe_allow_html=True)

cols = st.columns(len(PAGES), gap="small")

for col, label in zip(cols, PAGES):
    with col:
        active = st.session_state.page == label
        if st.button(
            label,
            key=f"nav_{label.lower().replace(' ', '_')}",
            use_container_width=True,
            type="primary" if active else "secondary",
        ):
            st.session_state.page = label
            st.rerun()

st.markdown("</div>", unsafe_allow_html=True)

page = st.session_state.page


# ============================================================
# HERO
# ============================================================
st.markdown(
    """
    <div class="hero">
        <div class="hero-kicker">01 / Network intelligence</div>
        <div class="hero-title">
            Diagnose with <span>evidence.</span><br>
            Evaluate with confidence.
        </div>
        <div class="hero-copy">
            NetSage combines deterministic network checks, grounded AI reasoning,
            human validation, and reliability analytics into one evaluation pipeline.
        </div>
        <div class="hero-pipeline">
            RULES  →  AI  →  GROUNDING  →  HUMAN  →  ANALYTICS
        </div>
    </div>
    """,
    unsafe_allow_html=True,
)


# ============================================================
# KPI STRIP
# ============================================================
st.markdown('<div class="section-head">System Snapshot</div>', unsafe_allow_html=True)

st.markdown(
    f"""
    <div class="kpi-grid">
        <div class="kpi">
            <div class="kpi-label">Cases evaluated</div>
            <div class="kpi-value">{total}</div>
            <div class="kpi-foot">{category_count} fault categories</div>
        </div>
        <div class="kpi">
            <div class="kpi-label">AI agreement</div>
            <div class="kpi-value green">{agreement:.1%}</div>
            <div class="kpi-foot">accepted without correction</div>
        </div>
        <div class="kpi">
            <div class="kpi-label">Human corrections</div>
            <div class="kpi-value amber">{corrections}</div>
            <div class="kpi-foot">{edited} edited · {rejected} rejected</div>
        </div>
        <div class="kpi">
            <div class="kpi-label">Grounding rate</div>
            <div class="kpi-value cyan">{grounded}/{total}</div>
            <div class="kpi-foot">{grounded/total:.1%} evidence verified</div>
        </div>
        <div class="kpi">
            <div class="kpi-label">Grounding flags</div>
            <div class="kpi-value {'red' if flags else 'green'}">{flags}</div>
            <div class="kpi-foot">automated evidence checks</div>
        </div>
    </div>
    """,
    unsafe_allow_html=True,
)


# ============================================================
# OVERVIEW
# ============================================================
if page == "Overview":
    left, right = st.columns([1, 1], gap="large")

    with left:
        st.markdown('<div class="section-head">AI vs Human Review</div>', unsafe_allow_html=True)

        decisions = (
            df["decision"]
            .value_counts()
            .reindex(["Accepted", "Edited", "Rejected"], fill_value=0)
            .reset_index()
        )
        decisions.columns = ["decision", "count"]

        fig = px.pie(
            decisions,
            names="decision",
            values="count",
            hole=.68,
            color="decision",
            color_discrete_map={
                "Accepted": "#39d98a",
                "Edited": "#ffbf55",
                "Rejected": "#ff6673",
            },
        )
        fig.update_traces(
            textinfo="percent",
            textfont=dict(color="#edf6fb", size=12),
            marker=dict(line=dict(color="#071019", width=2)),
        )
        st.plotly_chart(themed(fig, 340), use_container_width=True)

    with right:
        st.markdown('<div class="section-head">Case Distribution</div>', unsafe_allow_html=True)

        cat = df["category"].value_counts().sort_values().reset_index()
        cat.columns = ["category", "count"]

        fig = px.bar(
            cat,
            x="count",
            y="category",
            orientation="h",
            text="count",
        )
        fig.update_traces(
            textposition="outside",
            marker_color="#3bb8ed",
            hovertemplate="<b>%{y}</b><br>Cases: %{x}<extra></extra>",
        )
        st.plotly_chart(themed(fig, 340), use_container_width=True)

    # Quick evaluation health
    st.markdown('<div class="section-head">Evaluation Health</div>', unsafe_allow_html=True)

    q1, q2, q3, q4 = st.columns(4)
    q1.metric("Accepted", accepted)
    q2.metric("Edited", edited)
    q3.metric("Rejected", rejected)
    q4.metric("Grounding Flags", flags)

    if flags == 0:
        st.success("Grounding evaluator: all current diagnoses passed the automated evidence check.")
    else:
        st.warning(f"{flags} diagnosis(es) were flagged for additional evidence review.")


# ============================================================
# AI DIAGNOSIS
# ============================================================
elif page == "AI Diagnosis":
    st.markdown('<div class="section-head">AI Diagnosis Console</div>', unsafe_allow_html=True)

    ids = df["case_id"].astype(str).tolist()
    selected_id = st.selectbox("Select case", ids)

    row = df[df["case_id"].astype(str) == str(selected_id)].iloc[0]

    confidence = safe_text(row.get("ai_confidence"), "Unknown")
    decision = safe_text(row.get("decision"), "Unknown")
    grounded_state = "VERIFIED" if bool(row["grounded"]) else "FLAGGED"

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Case", safe_text(row.get("case_id")))
    c2.metric("Category", safe_text(row.get("category")))
    c3.metric("AI Confidence", confidence)
    c4.metric("Grounding", grounded_state)

    left, right = st.columns([1.35, 1], gap="large")

    with left:
        root = row.get("ai_root_cause", row.get("ai_root_cause ", ""))
        evidence = row.get("ai_evidence", "")
        command = row.get("ai_next_command", "")

        st.markdown(
            f"""
            <div class="diagnosis-card">
                <div class="diagnosis-id">{html.escape(str(selected_id))} / AI DIAGNOSIS</div>
                <div style="margin-top:10px">
                    <span class="badge">{html.escape(safe_text(row.get("category")))}</span>
                    <span class="badge">{html.escape(safe_text(row.get("severity")))}</span>
                    <span class="badge">{html.escape(confidence)}</span>
                </div>
                <div class="diagnosis-root">{html.escape(safe_text(root, "No AI root cause recorded."))}</div>
                <div class="evidence">
                    <b>Evidence used</b><br>
                    {html.escape(safe_text(evidence, "No evidence field recorded."))}
                </div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        st.markdown("#### Recommended verification command")
        st.code(safe_text(command, "No next command recorded."), language="text")

    with right:
        st.markdown('<div class="panel">', unsafe_allow_html=True)
        st.markdown('<div class="panel-title">Human Review</div>', unsafe_allow_html=True)
        st.markdown('<div class="panel-meta">VALIDATION / CORRECTION RECORD</div>', unsafe_allow_html=True)

        st.markdown(
            f"""
            <div class="audit-row">
                <div class="audit-key">Decision</div>
                <div class="audit-value">{html.escape(decision)}</div>
            </div>
            <div class="audit-row">
                <div class="audit-key">Grounding</div>
                <div class="audit-value">{grounded_state}</div>
            </div>
            <div class="audit-row">
                <div class="audit-key">Correction reason</div>
                <div class="audit-value">{html.escape(safe_text(row.get("correction_reason"), "None"))}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        corrected = safe_text(row.get("corrected_root_cause"), "")
        notes = safe_text(row.get("reviewer_notes"), "")

        st.markdown("**Corrected root cause**")
        st.write(corrected if corrected else "No correction recorded.")

        st.markdown("**Reviewer notes**")
        st.write(notes if notes else "No reviewer notes recorded.")

        st.markdown("</div>", unsafe_allow_html=True)


# ============================================================
# CASES
# ============================================================
elif page == "Cases":
    st.markdown('<div class="section-head">Case Explorer</div>', unsafe_allow_html=True)

    f1, f2, f3, f4 = st.columns(4)

    selected_categories = f1.multiselect(
        "Fault category",
        sorted(df["category"].dropna().unique()),
    )
    selected_decisions = f2.multiselect(
        "Human decision",
        sorted(df["decision"].dropna().unique()),
    )
    selected_severity = f3.multiselect(
        "Severity",
        sorted(df["severity"].dropna().unique()),
    )
    grounding_filter = f4.selectbox(
        "Grounding",
        ["All", "Grounded only", "Flagged only"],
    )

    filtered = df.copy()

    if selected_categories:
        filtered = filtered[filtered["category"].isin(selected_categories)]
    if selected_decisions:
        filtered = filtered[filtered["decision"].isin(selected_decisions)]
    if selected_severity:
        filtered = filtered[filtered["severity"].isin(selected_severity)]
    if grounding_filter == "Grounded only":
        filtered = filtered[filtered["grounded"]]
    elif grounding_filter == "Flagged only":
        filtered = filtered[~filtered["grounded"]]

    display_cols = [
        "case_id",
        "category",
        "severity",
        "ai_confidence",
        "decision",
        "grounded",
        "correction_reason",
    ]
    display_cols = [c for c in display_cols if c in filtered.columns]

    st.caption(f"{len(filtered)} of {total} cases shown")
    st.dataframe(filtered[display_cols], use_container_width=True, hide_index=True)

    if len(filtered):
        st.markdown('<div class="section-head">Selected Case</div>', unsafe_allow_html=True)

        selected_case = st.selectbox(
            "Inspect case",
            filtered["case_id"].astype(str).tolist(),
            key="case_inspector",
        )
        selected = filtered[filtered["case_id"].astype(str) == str(selected_case)].iloc[0]

        a, b, c, d = st.columns(4)
        a.metric("Case", safe_text(selected.get("case_id")))
        b.metric("Category", safe_text(selected.get("category")))
        c.metric("Severity", safe_text(selected.get("severity")))
        d.metric("Decision", safe_text(selected.get("decision")))

        l, r = st.columns(2)

        with l:
            st.markdown("#### AI Diagnosis")
            st.write(safe_text(selected.get("ai_root_cause")))
            st.markdown("**Evidence**")
            st.write(safe_text(selected.get("ai_evidence")))
            st.markdown("**Next command**")
            st.code(safe_text(selected.get("ai_next_command")), language="text")

        with r:
            st.markdown("#### Human Review")
            st.markdown(f"**Decision:** {safe_text(selected.get('decision'))}")
            st.markdown(f"**Grounding:** {'VERIFIED' if bool(selected.get('grounded')) else 'FLAGGED'}")
            st.markdown("**Correction reason**")
            st.write(safe_text(selected.get("correction_reason"), "None"))
            st.markdown("**Corrected root cause**")
            st.write(safe_text(selected.get("corrected_root_cause"), "No correction recorded."))
            st.markdown("**Reviewer notes**")
            st.write(safe_text(selected.get("reviewer_notes"), "No reviewer notes."))


# ============================================================
# EVALUATION
# ============================================================
elif page == "Evaluation":
    st.markdown('<div class="section-head">Reliability Evaluation</div>', unsafe_allow_html=True)

    left, right = st.columns(2, gap="large")

    with left:
        st.markdown("#### Confidence vs Human Outcome")

        confidence_order = ["Low", "Medium", "High"]
        calib = (
            df.groupby(["ai_confidence", "decision"])
            .size()
            .reset_index(name="count")
        )
        calib["ai_confidence"] = pd.Categorical(
            calib["ai_confidence"],
            categories=confidence_order,
            ordered=True,
        )
        calib = calib.sort_values("ai_confidence")

        fig = px.bar(
            calib,
            x="ai_confidence",
            y="count",
            color="decision",
            barmode="stack",
            text="count",
            category_orders={"ai_confidence": confidence_order},
            color_discrete_map={
                "Accepted": "#39d98a",
                "Edited": "#ffbf55",
                "Rejected": "#ff6673",
            },
        )
        fig.update_traces(textposition="inside")
        st.plotly_chart(themed(fig, 370), use_container_width=True)

        high_conf_corrections = int(
            ((df["ai_confidence"] == "High") & (df["decision"] != "Accepted")).sum()
        )
        st.info(f"High-confidence diagnoses requiring correction: {high_conf_corrections}")

    with right:
        st.markdown("#### Agreement by Fault Category")

        perf = (
            df.groupby("category")
            .agg(
                Cases=("case_id", "count"),
                Accepted=("decision", lambda x: (x == "Accepted").sum()),
            )
            .reset_index()
        )
        perf["Agreement"] = perf["Accepted"] / perf["Cases"]
        perf = perf.sort_values("Agreement")

        fig = px.bar(
            perf,
            x="Agreement",
            y="category",
            orientation="h",
            text=perf["Agreement"].map(lambda x: f"{x:.0%}"),
        )
        fig.update_traces(
            textposition="outside",
            marker_color="#3bb8ed",
        )
        fig.update_xaxes(range=[0, 1], tickformat=".0%")
        st.plotly_chart(themed(fig, 370), use_container_width=True)

    st.markdown('<div class="section-head">Correction Taxonomy</div>', unsafe_allow_html=True)

    if "correction_reason" in df.columns:
        reasons = df["correction_reason"].fillna("").astype(str).str.strip()
        reasons = reasons[reasons != ""]

        if len(reasons):
            rc = reasons.value_counts().reset_index()
            rc.columns = ["reason", "count"]

            fig = px.bar(
                rc,
                x="count",
                y="reason",
                orientation="h",
                text="count",
            )
            fig.update_traces(
                textposition="outside",
                marker_color="#ffbf55",
            )
            st.plotly_chart(themed(fig, 330), use_container_width=True)
        else:
            st.info("No correction reasons recorded yet.")


